def _g1_run(claim, tldr, ip, v="true", way=P):
    with db.get_conn() as _conn:
        _conn.execute("DELETE FROM verdict_cache WHERE claim_key = ?", (db.normalize_claim(claim),))
        _conn.execute("DELETE FROM query_cache")
