_pr_txt = ["Study ٣ found it", "éStudy 2 found it", "XStudy 2 found it", "_Study 2", "Studies 1, 2 and 3 agree",
           "study 2 and Study 9", "Study\u00a01 too", "Studies 2 & 3"]
_pr_py = [str(_dsp.desk_refs(x, 3)) for x in _pr_txt]
