# Its plain twin: the same row with every " ' < > & taken out, so the two must draw the same elements.
def _r4_plain(v):
    if isinstance(v, str):
        return re.sub(r"[\"'<>&]", "", v)
    if isinstance(v, list):
        return [_r4_plain(x) for x in v]
    if isinstance(v, dict):
        return {k: _r4_plain(x) for k, x in v.items()}
    return v


