# ---- K2: no regex lookbehind in a shipped script ------------------------------
# Safari before 16.4 cannot parse (?<= or (?<!, and one in app.js stops the whole
# script there. splitSentences now splits without one; the old regex is kept here
# as the reference, and the new function must return exactly what it returned.
_K2_OLD = r'''const oldSplit = (text) =>
  String(text || "").trim().split(/(?<=[.!?])\s+(?=[A-Z0-9\u201c"(])/).map((x) => x.trim()).filter(Boolean);
'''
_K2_CASES = [
    "", "   ", None, "One sentence.", "One sentence", "First. Second. Third.",
    "It works. 3.5 times more. Then it stops.", "Use e.g. this one. And that.",
    "Is it true? Yes! Maybe.", "Odd?!  Next one.", "She said \"no.\" Then left.",
    "He wrote. “Quoted start.” Done.", "A claim. (In brackets.) After.",
    "No space.After stop. Next.", "Several.     Spaces here.", "Line one.\nLine two.",
    "Tab.\tAfter tab.", "Ends. 42 people took part.", "Ends. 2024 was the year.",
    "Lower. not a split here.", "Version 1.2.3 Released. Good.",
    "Dr. Smith said so. Mr. Jones too.", "Done. ‘single curly’ not split.",
    "Mixed!? (Bracket.) “Quote.” 7 more.", "Wait...  Then go.",
    "Trailing space. ", "  Leading. Space.", "Stop. Nbsp space. End.",
    "Q? \"Straight quote.\" A.", "Ellipsis. . . Then on.", "x. . Y", "?! A", "a.\n\n\nB. C",
]
if _shutil.which("node"):
    _k2_js = (ROOT / "static" / "app.js").read_text()
    _k2_fn = _k2_js[_k2_js.index("const splitSentences"):_k2_js.index("const sentenceKey")]
    _k2_out = json.loads(_subprocess.run(
        ["node", "-e", _K2_OLD + _k2_fn + "const C = " + json.dumps(_K2_CASES) + ";"
         "console.log(JSON.stringify(C.map((c) => [oldSplit(c), splitSentences(c)])));"],
        capture_output=True, text=True, check=True).stdout)
    _k2_diff = [(c, o, n) for c, (o, n) in zip(_K2_CASES, _k2_out) if o != n]
    t("K2: splitSentences returns exactly what the old lookbehind regex returned, on %d strings" % len(_K2_CASES),
      len(_K2_CASES) >= 25 and not _k2_diff and any(len(o) > 2 for o, _ in _k2_out), _k2_diff[:3])
else:
    # L5: with no node the comparison cannot run; say so as a failure rather than pass in silence.
    t("K2: splitSentences returns exactly what the old lookbehind regex returned (node is needed and was not found)", False)
t("L5: the K2 comparison records a visible failure when node is missing, never a silent skip",
  "_k2_diff[:3])\nelse:\n    # L5" in (ROOT / "tests" / "test_app.py").read_text())
_k2_files = {f: (ROOT / "static" / f).read_text() for f in ("app.js", "desk.js", "desk3d.js", "sw.js")}
t("K2: app.js, desk.js, desk3d.js and sw.js hold no regex lookbehind, so Safari before 16.4 can parse them",
  not [f for f, s in _k2_files.items() if "(?<=" in s or "(?<!" in s],
  [f for f, s in _k2_files.items() if "(?<=" in s or "(?<!" in s])

# ---- check speed (q10 5a): the replay tools that prove a faster check says the same ----
import threading as _sp_threading  # noqa: E402
import importlib.util as _sp_imp  # noqa: E402
sys.path.insert(0, str(ROOT / "scripts"))
import harness as _sp_harness  # noqa: E402
_sp_spec = _sp_imp.spec_from_file_location("replay_compare", ROOT / "scripts" / "replay_compare.py")
_sp_rc = _sp_imp.module_from_spec(_sp_spec)
_sp_spec.loader.exec_module(_sp_rc)
_sp_dir = pathlib.Path(tempfile.mkdtemp(prefix="speed-"))


def _sp_write(name, rows):
    d = _sp_dir / name
    d.mkdir(parents=True, exist_ok=True)
    (d / "results.jsonl").write_text("".join(json.dumps(r) + "\n" for r in rows))
    return str(d)


def _sp_row(i, verdict_="true", t0=1.0, pubmed_n=5):
    return {"id": i, "http_status": 200, "status": 200, "verdict": verdict_,
            "response": {"verdict": verdict_, "tldr": "x"}, "wall": t0 + 0.1,
            "events": [{"stage": "search", "t": 0.0, "took": 0.0},
                       {"stage": "done", "t": t0, "took": t0}],
            "harness": {"model_calls": 3, "model_tries": 3, "pubmed_requests": pubmed_n, "misses": []}}


_sp_a = _sp_write("a", [_sp_row("1"), _sp_row("2")])
_sp_b = _sp_write("b", [_sp_row("1", t0=0.5), _sp_row("2", t0=0.4)])
_sp_c = _sp_write("c", [_sp_row("1", "false"), _sp_row("2", pubmed_n=6)])
_sp_code, _sp_text = _sp_rc.report(_sp_a, _sp_b, quiet=True)
t("speed: replay_compare counts results the same apart from their timing fields as identical",
  _sp_code == 0 and "identical apart from timing: 2 of 2" in _sp_text
  and "done at median 1.00s" in _sp_text and "done at median 0.45s" in _sp_text, _sp_text)
_sp_code, _sp_text = _sp_rc.report(_sp_a, _sp_c, quiet=True)
t("  and names a changed answer's keys and a claim whose request counts differ, and fails",
  _sp_code == 1 and "identical apart from timing: 1 of 2" in _sp_text
  and "response.verdict" in _sp_text and "claims whose request counts differ: 1" in _sp_text, _sp_text)

# Latency replay keeps PubMed's spacing of starts, so searches run side by
# side cannot time faster than NCBI allows.
_sp_store = _sp_dir / "store"
_sp_keys = []
for _i in range(4):
    _req = _sp_harness.pubmed_request("esearch.fcgi", {"term": f"q{_i}"})
    _k = _sp_harness.key_of(_req)
    _sp_harness.Store(_sp_store).put("pubmed", _k, {
        "kind": "pubmed", "key": _k, "request": _req, "ms": 50,
        "response": {"status_code": 200, "encoding": "utf-8", "content_type": "application/json",
                     "text": "{}"}})
_sp_min, _sp_starts = pubmed.MIN_INTERVAL, []
pubmed.MIN_INTERVAL = 0.1
_sp_h = _sp_harness.install("replay", str(_sp_store), latency=True)
_sp_real_space = _sp_h._space_start
_sp_h._space_start = lambda: (_sp_real_space(), _sp_starts.append(_time.monotonic()))
_sp_threads = [_sp_threading.Thread(target=pubmed._paced_get, args=("esearch.fcgi", {"term": f"q{_i}"}))
               for _i in range(4)]
for _th in _sp_threads:
    _th.start()
for _th in _sp_threads:
    _th.join()
_sp_h.uninstall()
pubmed.MIN_INTERVAL = _sp_min
_sp_starts.sort()
t("  a latency replay spaces PubMed starts across threads as _paced_get does, and misses nothing",
  len(_sp_starts) == 4 and min(b - a for a, b in zip(_sp_starts, _sp_starts[1:])) >= 0.095
  and not _sp_h.misses and _sp_h.snapshot()["pubmed_replayed"] == 4, (_sp_starts, _sp_h.misses))

# Task 2: the guidance view starts beside the verdict call, on the claim
# alone, and is used where it always was.
_sp_log = []
_sp_real_gen = fg.models.generate_content
_sp_prev_view = verdict.guideline_view


def _sp_slow_gen(**kw):
    _sp_log.append(("model", _time.monotonic()))
    _time.sleep(0.25)
    return _sp_real_gen(**kw)


def _sp_slow_view(claim):
    _sp_log.append(("guidance", _time.monotonic()))
    _time.sleep(0.25)
    return {"verdict": "true", "says": "sugar does not change how children behave.", "bodies": ["NHS"]}


def _sp_weigh(claim):
    del _sp_log[:]
    fg.models.calls = 0
    fg.models.script = [_SUGAR_NO, DIR("no"),
                        Resp(VJ("false", [1, 2], tldr=_NO_TLDR,
                                evidence=["Sugar did not change behaviour (Study 1)."]))]
    t0 = _time.monotonic()
    out = verdict.weigh_evidence(claim, [dict(s_) for s_ in _SUGAR], "(sugar) AND (hyperactivity)")
    return out, _time.monotonic() - t0, list(_sp_log), fg.models.calls


fg.models.generate_content = _sp_slow_gen
verdict.guideline_view = _sp_slow_view
try:
    _sp_fast = _sp_weigh("Sugar in pregnancy makes children hyperactive")
    _sp_real_ahead = verdict.guidance_ahead
    verdict.guidance_ahead = lambda claim: None      # today's order: guidance last, in line
    try:
        _sp_serial = _sp_weigh("Sugar in pregnancy makes children hyperactive")
    finally:
        verdict.guidance_ahead = _sp_real_ahead
    _sp_plain = _sp_weigh("Sugar makes people hyperactive")
finally:
    fg.models.generate_content = _sp_real_gen
    verdict.guideline_view = _sp_prev_view
    fg.models.script = []
