    e_ = _sl.BY_ID.get(i_)
    tx_ = _sl.normalise(c_)
    if (not e_ or _sl._fires(e_, tx_) or not all(p_.search(tx_) for p_ in e_["_when"])
            or any(p_.search(tx_) for j_, p_ in enumerate(e_["_unless"]) if j_ != k_)):
        _sl_xbad.append((i_, k_))
