def _e3_rct(title, concl):
    return {"pmid": "1", "title": title, "abstract": f"METHODS: 200 adults. CONCLUSIONS: {concl}",
            "publication_types": ["Journal Article", "Randomized Controlled Trial"], "year": "2020"}


